    D2_FREE_AT(pQServer->ppModePacketQueueHeads, ".\\Src\\QServer\\QServer.cpp", 0x18d);
    D2_FREE_AT(pQServer->ppModePacketQueueTails, ".\\Src\\QServer\\QServer.cpp", 0x18e);
